package fe8.testing

import java.io.File

/**
 * Exact RAM addresses of the original game's variables, from `reference/ram_symbols.tsv` (generated by
 * `tools/gen_reference.py --nm` from the decomp ELF built in the ROM repo's `decomp-map` workflow).
 *
 * Differential tests use this to find the original game's state inside mGBA RAM dumps by the decomp's
 * names. Test-only: GBA addresses must never be used by the port itself.
 */
public class RamSymbols(file: File) {
    /** One symbol. [binding] is `global` or `local` (C `static`). */
    public data class Symbol(val name: String, val address: Int, val size: Int, val binding: String)

    private val byName: Map<String, List<Symbol>> = file.readLines().drop(1).filter { it.isNotBlank() }.map { line ->
        val c = line.split('\t')
        Symbol(c[0], c[1].removePrefix("0x").toLong(16).toInt(), c[2].toInt(), c[3])
    }.groupBy { it.name }

    /** The unique symbol called [name]; fails if missing or ambiguous (same static name in several files). */
    public operator fun get(name: String): Symbol {
        val all = byName[name] ?: error("RAM symbol '$name' not in ram_symbols.tsv")
        require(all.size == 1) { "RAM symbol '$name' is ambiguous (${all.size} definitions)" }
        return all[0]
    }

    public companion object {
        /** Loads from the `fe8.reference` system property (set by Gradle to `<repo>/reference`). */
        public fun fromEnvironment(): RamSymbols =
            RamSymbols(File(System.getProperty("fe8.reference") ?: "reference", "ram_symbols.tsv"))
    }
}
